contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address to, uint256 amount) public {
        require(to != address(0));
        // ensure sender (this contract) has enough tokens
        c.approve(address(this), 0);
        bool ap = c.approve(address(this), type(uint256).max);
        require(ap);
        bool ok = c.transferFrom(address(this), address(this), 0);
        require(ok);

        // fund this contract by transferring from owner? Instead use allowance path:
        // Simpler: pick sender = this contract. Give it tokens via getTokens if possible.
        // Use a transfer and check conservation.
        uint256 balBefore = c.balanceOf(address(this));
        uint256 toBalBefore = c.balanceOf(to);
        bool reverted;
        if (amount <= balBefore) {
            bool success = c.transfer(to, amount);
            require(success);
            reverted = false;
        } else {
            try c.transfer(to, amount) { reverted = false; } catch { reverted = true; }
        }
        uint256 balAfter = c.balanceOf(address(this));
        uint256 toBalAfter = c.balanceOf(to);
        if (reverted) {
            assert(balAfter == balBefore && toBalAfter == toBalBefore);
        } else {
            assert(balAfter + toBalAfter == balBefore + toBalBefore
                   && balAfter == balBefore - amount
                   && toBalAfter == toBalBefore + amount);
        }
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address to, uint256 k) public {
        require(to != address(0));
        require(k <= 1000 * 10**18);
        // acquire airdrop tokens: msg.sender (this contract) gets exactly the current value 1000e18
        c.getTokens();
        uint256 myBal = c.balanceOf(address(this));
        require(myBal == 1000 * 10**18);
        uint256 toBefore = c.balanceOf(to);
        // grant allowance of k to this contract (it is also the spender for transferFrom)
        bool ap = c.approve(address(this), k);
        require(ap);
        uint256 allowBefore = c.allowance(address(this), address(this));
        require(allowBefore == k);
        // deciding call
        bool s = c.transferFrom(address(this), to, k);
        uint256 myAfter = c.balanceOf(address(this));
        uint256 toAfter = c.balanceOf(to);
        uint256 allowAfter = c.allowance(address(this), address(this));
        assert(
            s == true &&
            myAfter == myBal - k &&
            toAfter == toBefore + k &&
            allowAfter == allowBefore - k
        );
    }
    receive() external payable {}
}

